5.3.3 配当利回り

tbl_dividend_yield_2020 &lt;- tbl_monthly |&gt;
  filter(year == 2020) |&gt;
  group_by(firm_ID) |&gt;
  summarise(
    annual_dividend = sum(
      DPS * shares_outstanding,
      na.rm = TRUE
    ),
    latest_ME = ME[which.max(month_ID)],
    .groups = "drop"
  ) |&gt;
  mutate(
    dividend_yield = annual_dividend / latest_ME
  ) |&gt;
  filter(
    is.finite(dividend_yield),
    dividend_yield &gt; 0
  )

