6.2.7 欠損値の確認

missing_summary &lt;- list(
  individual_returns = return_data,
  market_returns = market_return_data,
  events = event_data
) |&gt;
  imap_dfr(
    \(data, data_name) {
      data |&gt;
        summarise(
          across(
            everything(),
            list(
              missing =
                \(x) sum(is.na(x)),
              missing_rate =
                \(x) mean(is.na(x))
            ),
            .names = "{.col}__{.fn}"
          )
        ) |&gt;
        pivot_longer(
          cols = everything(),
          names_to = c(
            "variable",
            ".value"
          ),
          names_sep = "__"
        ) |&gt;
        mutate(
          data = data_name,
          .before = 1
        )
    }
  ) |&gt;
  arrange(
    data,
    desc(missing_rate),
    variable
  )

